// node's `Buffer` (T56): errors and edge cases (read/write offsets and ranges, argument forms,
// invalid UTF-8, `from` of views, printing).
import util from "node:util";
const show = (label, f) => { try { const v = f(); console.log(label, v); } catch (e) { console.log(label, "THROWS", e.name, e.code, e.message); } };
const b = Buffer.from([1, 2, 3, 4, 5, 6, 7, 8]);
show("readU default", () => [b.readUInt8(), b.readUInt16BE(), b.readUInt32LE(), b.readInt8(7)]);
show("read neg", () => b.readUInt8(-1));
show("read frac", () => b.readUInt16LE(1.5));
show("read str", () => b.readUInt8("1"));
show("read small", () => Buffer.alloc(1).readUInt32LE(0));
show("readUIntLE bl", () => b.readUIntLE(0, 7));
show("readUIntLE noOff", () => b.readUIntLE());
show("readIntBE", () => [b.readIntBE(0, 6), b.readUIntLE(2, 3), b.readIntLE(1, 1)]);
show("write range", () => b.writeInt8(-129));
show("write u32", () => b.writeUInt32LE(2 ** 32));
show("write int48", () => b.writeIntLE(2 ** 47, 0, 6));
show("write off", () => b.writeUInt16LE(1, 7));
show("write float off", () => b.writeFloatLE(1, 6));
show("write ret", () => [b.writeUInt8(9, 0), b.writeDoubleLE(1.5, 0), b.writeUIntBE(1, 2, 3)]);
show("bigint range", () => b.writeBigUInt64LE(-1n));
show("proto", () => [Object.getPrototypeOf(Buffer.prototype) === Uint8Array.prototype, Object.getPrototypeOf(Buffer) === Uint8Array, b instanceof Buffer, b.constructor === Buffer, Buffer.name, Buffer.length]);
show("call no new", () => [Buffer(3).length, Buffer("ab").toString(), new Buffer([1]).length]);
show("utf8 invalid", () => JSON.stringify(Buffer.from([0x61, 0xff, 0xc3, 0x28, 0xe2, 0x82]).toString()));
show("utf16 odd", () => JSON.stringify(Buffer.from([0x61, 0x00, 0x62]).toString("utf16le")));
show("ascii high", () => JSON.stringify(Buffer.from([0xe9, 0x41]).toString("ascii")));
show("write enc", () => { const t = Buffer.alloc(8); return [t.write("aGk=", "base64"), t.write("ff00", 2, "hex"), t.write("é", 4, 1, "latin1"), t.toString("hex")]; });
show("write oob", () => Buffer.alloc(2).write("x", 3));
show("fill err", () => Buffer.alloc(2).fill("x", 0, 5));
show("fill enc", () => Buffer.alloc(2).fill("x", "nope"));
show("toString enc", () => b.toString("nope"));
show("from enc", () => Buffer.from("x", "nope"));
show("from buf", () => { const a = Buffer.from("ab"); const c = Buffer.from(a); c[0] = 0x7a; return [a.toString(), c.toString()]; });
show("from u16", () => Buffer.from(new Uint16Array([0x102, 0x304])).toJSON().data);
show("from ab share", () => { const u = new Uint16Array([1, 2]); const x = Buffer.from(u.buffer); x[0] = 9; return [u[0], x.length]; });
show("from json", () => Buffer.from({ type: "Buffer", data: [1, 2] }).toJSON().data);
show("from ab off", () => Buffer.from(new ArrayBuffer(4), 5));
show("byteLength", () => [Buffer.byteLength(b), Buffer.byteLength(new ArrayBuffer(3)), Buffer.byteLength("aa", "hex"), Buffer.byteLength("€", "utf16le")]);
show("byteLength bad", () => Buffer.byteLength(5));
show("concat bad", () => Buffer.concat([1]));
show("concat not arr", () => Buffer.concat("x"));
show("compare bad", () => Buffer.compare(1, b));
show("copy", () => { const t = Buffer.alloc(3); return [b.copy(t), b.copy(t, 2, 6), t.toJSON().data]; });
show("reverse", () => Buffer.isBuffer(b.reverse()));
show("keys", () => [...Buffer.from("ab").keys()]);
show("lastIndexOf", () => [Buffer.from("abcabc").lastIndexOf("b"), Buffer.from("abcabc").lastIndexOf("b", 3), Buffer.from("abc").indexOf("c", -1), Buffer.from("abc").indexOf(99, "latin1")]);
show("inspect", () => util.inspect(Buffer.from("x")));
show("str", () => String(Buffer.from("hi")) + Buffer.from("!"));
console.log(Buffer.alloc(0), Buffer.from("a"), { b: Buffer.from([255, 0]) });
show("utf8 more", () => [0xe0, 0x80, 0xed, 0xa0, 0x80, 0xf0, 0x90, 0x80, 0xf4, 0x90, 0x80, 0x80, 0xc0, 0xaf, 0xf8].map((x, i, a) => JSON.stringify(Buffer.from(a.slice(i, i + 3)).toString())).join(" "));
show("write args", () => { const t = Buffer.alloc(4); return [t.write("ab", 1, 1), t.write("cd", "latin1"), t.write("z", 2, "utf8"), t.toString()]; });
show("write bad", () => Buffer.alloc(2).write(5));
show("fill ok", () => [Buffer.alloc(4).fill("ab", 1).toString("hex"), Buffer.alloc(3).fill("x", 1, 1).toString("hex"), Buffer.alloc(3).fill(Buffer.from([7])).toJSON().data]);
show("fill frac", () => Buffer.alloc(3).fill(1, 0.5));
